// `QuantizedRow` is otherwise only constructed inside `quantize_row`; touch
// it directly once so a future refactor cannot silently drop a field
// without a compile error here.
#[test]
fn quantized_row_fields_are_reachable() {
    let row = QuantizedRow {
        norm: 1.0,
        words: vec![0, 1],
    };
    assert_eq!(row.norm, 1.0);
    assert_eq!(row.words, vec![0, 1]);
}
